"use strict";(function(){let showSpinner=!1;window.onbeforeunload=function(){if(!showSpinner)return;document.querySelector("body").classList.add("rpb-reloading");let div=document.createElement("div");div.id="rpb-reloading";div.innerHTML='<span class="loader"></span>';document.body.appendChild(div);setTimeout(()=>{div.classList.add("show")},10)};window.addEventListener("click",(e)=>{let button=e.target.closest(".ui-dialog-buttonset button");if(!button)return;showSpinner=!0})})()